/**
 * A month grid for choosing a date (`design/components/calendar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/calendar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/date-picker'

import {
  MEMBER_PROVIDERS,
  Ref,
  Spread,
  agentDate,
  agentMember,
  cell,
  derived,
  elementRef,
  mergeParts,
  mountEffect,
  normalizeProps,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  watchEffect,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/controls/calendar.module.css'
import { Button, type ButtonProps } from './Button'

export type FirstDayOfWeek = NonNullable<CalendarProps['firstDayOfWeek']>

export type CalendarDate = zag.CalendarDate

export interface CalendarMessages {
  previousMonth: string
  nextMonth: string
}

/** A month grid for choosing a date: the inputs it takes, by the React member's prop names. */
export interface CalendarProps {
  /**
   * Names the calendar from outside, as DatePicker's popup does.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  defaultValue?: CalendarDate | null
  /**
   * Disables the whole grid.
   */
  disabled?: boolean
  /**
   * Overrides the locale's first day of the week.
   */
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  /**
   * Controlled month navigation, for apps that need it.
   */
  focusedValue?: CalendarDate
  /**
   * App policy, such as booked-out days. Unavailable is not the same as disabled.
   */
  isDateUnavailable?: (date: CalendarDate) => boolean
  /**
   * Drives names, numbering and the week's first day. Defaults to the app's.
   */
  locale?: string
  maxValue?: CalendarDate
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: CalendarMessages
  minValue?: CalendarDate
  value?: CalendarDate | null
}

/** A month grid for choosing a date. */
@Component({
  selector: 'pm-calendar',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Spread, Button],
  // prettier-ignore
  template: `<!-- root -->
<div
[pmSpread]="e1()"
[pmRef]="root"
><!-- header -->
<div
[attr.class]="e2()"
(focusin)="h1()"
(focusout)="h2($event)"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e3()"
icon="previous"
[label]="e4()"
[disabled]="e5()"
(click)="h3()"
></pm-button>
<!-- title -->
<span
[attr.class]="e6()"
aria-live="polite"
>{{ e7() }}</span>
<pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e3()"
icon="next"
[label]="e8()"
[disabled]="e9()"
(click)="h4()"
></pm-button></div>
<!-- grid -->
<table
[pmSpread]="e10()"
><thead
aria-hidden="true"
><tr>@for (weekday of e11(); track e12(weekday)) {<th
scope="col"
[attr.aria-label]="e12(weekday)"
><span
aria-hidden="true"
>{{ e13(weekday) }}</span></th>}</tr></thead>
<tbody>@for (week of e14(); track e15($index); let at = $index) {<tr>@for (day of e16(week); track e17(day)) {@if (e18(day)) {<td></td>} @else {<td
[attr.class]="e19(day)"
role="gridcell"
[attr.aria-disabled]="e20(day)"
[attr.aria-selected]="e21(day)"
><!-- day -->
<div
[pmSpread]="e22(day)"
>{{ e23(day) }}</div></td>}}</tr>}</tbody></table></div>`,
})
export class Calendar {
  /**
   * Names the calendar from outside, as DatePicker's popup does.
   */
  readonly ariaLabel = input<CalendarProps['aria-label']>(undefined, { alias: 'aria-label' })
  readonly ariaLabelledby = input<CalendarProps['aria-labelledby']>(undefined, {
    alias: 'aria-labelledby',
  })
  readonly defaultValue = input<CalendarProps['defaultValue']>(undefined)
  /**
   * Disables the whole grid.
   */
  readonly disabled = input<
    Exclude<CalendarProps['disabled'], undefined>,
    CalendarProps['disabled']
  >(false, {
    transform: (value: CalendarProps['disabled']) => (value === undefined ? false : value),
  })
  /**
   * Overrides the locale's first day of the week.
   */
  readonly firstDayOfWeek = input<CalendarProps['firstDayOfWeek']>(undefined)
  /**
   * Controlled month navigation, for apps that need it.
   */
  readonly focusedValue = input<CalendarProps['focusedValue']>(undefined)
  /**
   * App policy, such as booked-out days. Unavailable is not the same as disabled.
   */
  readonly isDateUnavailable = input<CalendarProps['isDateUnavailable']>(undefined)
  /**
   * Drives names, numbering and the week's first day. Defaults to the app's.
   */
  readonly locale = input<CalendarProps['locale']>(undefined)
  readonly maxValue = input<CalendarProps['maxValue']>(undefined)
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  readonly messages = input<CalendarProps['messages']>(undefined)
  readonly minValue = input<CalendarProps['minValue']>(undefined)
  readonly value = input<CalendarProps['value']>(undefined)
  readonly onChange = output<CalendarDate | null>({ alias: 'change' })
  readonly onFocusChange = output<CalendarDate>({ alias: 'focusChange' })
  protected readonly $ = useMember({
    events: ['change', 'focusChange'],
    props: {
      'aria-label': () => this.ariaLabel(),
      'aria-labelledby': () => this.ariaLabelledby(),
      defaultValue: () => this.defaultValue(),
      disabled: () => this.disabled(),
      firstDayOfWeek: () => this.firstDayOfWeek(),
      focusedValue: () => this.focusedValue(),
      isDateUnavailable: () => this.isDateUnavailable(),
      locale: () => this.locale(),
      maxValue: () => this.maxValue(),
      messages: () => this.messages(),
      minValue: () => this.minValue(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly browserLanguage = cell(() => undefined as string | undefined)
  protected readonly travel = cell(() => 'next')
  protected readonly shownMonth = cell(() => '')
  protected readonly monthButton = cell(() => false)
  protected readonly root = elementRef<HTMLElement>()
  protected readonly say = derived(
    () => this.$p.messages ?? { previousMonth: 'Previous month', nextMonth: 'Next month' },
  )
  protected readonly language = derived(
    () => this.$p.locale ?? this.browserLanguage.value ?? 'en-US',
  )
  protected readonly english = derived(() => this.language.value.toLowerCase().startsWith('en'))
  protected readonly zone = derived(() => Intl.DateTimeFormat().resolvedOptions().timeZone)
  protected readonly dayName = derived(
    () => (date: zag.DateValue, text: string, today: boolean, selected: boolean) => {
      if (!this.english.value) return text
      const said = today
        ? selected
          ? `Today, ${text} selected`
          : `Today, ${text}`
        : selected
          ? `${text} selected`
          : text
      if (this.$p.minValue !== undefined && date.compare(this.$p.minValue) === 0)
        return `${said}, First available date`
      if (this.$p.maxValue !== undefined && date.compare(this.$p.maxValue) === 0)
        return `${said}, Last available date`
      return said
    },
  )
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          inline: true,
          locale: this.language.value,
          timeZone: this.zone.value,
          value:
            this.$p.value === undefined ? undefined : this.$p.value === null ? [] : [this.$p.value],
          defaultValue: this.$p.defaultValue == null ? undefined : [this.$p.defaultValue],
          min: this.$p.minValue,
          max: this.$p.maxValue,
          focusedValue: this.$p.focusedValue,
          startOfWeek: this.$p.firstDayOfWeek,
          disabled: this.$p.disabled,
          isDateUnavailable:
            this.$p.isDateUnavailable === undefined
              ? undefined
              : (date) => this.$p.isDateUnavailable?.(date as zag.CalendarDate) === true,
          onValueChange: (details) => {
            this.$.emit(
              this.onChange,
              'onChange',
              (details.value[0] as zag.CalendarDate | undefined) ?? null,
            )
          },
          onFocusChange: (details) => {
            this.$.emit(
              this.onFocusChange,
              'onFocusChange',
              details.focusedValue as zag.CalendarDate,
            )
          },
          onVisibleRangeChange: (details) => {
            void ((this.travel.value =
              this.shownMonth.value !== '' &&
              details.visibleRange.start.toString() < this.shownMonth.value
                ? 'previous'
                : 'next'),
            (this.shownMonth.value = details.visibleRange.start.toString()))
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly named = derived(() =>
    [this.$p['aria-label'], this.api.value.visibleRangeText.formatted].filter(Boolean).join(', '),
  )
  protected readonly monthButtonsOff = derived(
    () =>
      `${this.api.value.getPrevTriggerProps().disabled === true} ${this.api.value.getNextTriggerProps().disabled === true}`,
  )
  protected readonly dayOf = derived(() => (date: zag.DateValue) => {
    const cell = this.api.value.getDayTableCellState({ value: date })
    const off = this.$p.disabled || cell.invalid
    const refused = this.$p.isDateUnavailable?.(date as zag.CalendarDate) === true
    const selected = cell.selected && !off && !refused
    return {
      date,
      cell,
      off,
      unavailable: refused,
      outside: cell.outsideRange,
      selectable: !off && !refused,
      selected,
      name: this.dayName.value(date, cell.valueText, cell.today, selected),
    }
  })
  protected readonly weeks = derived(() =>
    this.api.value.weeks.map((week) => week.map((date) => this.dayOf.value(date))),
  )
  private release4: (() => void) | undefined

  constructor() {
    mountEffect(() => this.effect1())
    mountEffect(() => this.effect2())
    watchEffect(
      () => this.monthButtonsOff.value,
      () => this.effect3(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release4?.())
    mountEffect(() => this.effect4())
  }

  protected e1() {
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.root,
      hidden: undefined,
      tabindex: undefined,
      'data-state': undefined,
      role: 'application',
      'aria-label': this.named.value,
      'aria-labelledby': this.$p['aria-labelledby'],
      'data-member': 'calendar',
    })
  }

  protected e2() {
    return styles.header
  }

  protected h1(): void {
    this.monthButton.value = true
  }

  protected h2($event: FocusEvent): void {
    this.monthButton.value = ($event.target as HTMLButtonElement).disabled === true
  }

  protected e3(): ButtonProps['iconOnly'] {
    return true
  }

  protected e4(): ButtonProps['label'] {
    return this.say.value.previousMonth
  }

  protected e5(): ButtonProps['disabled'] {
    return this.api.value.getPrevTriggerProps().disabled === true
  }

  protected h3(): void {
    this.api.value.goToPrev()
  }

  protected e6() {
    return styles.title
  }

  protected e7() {
    return this.api.value.visibleRangeText.formatted
  }

  protected e8(): ButtonProps['label'] {
    return this.say.value.nextMonth
  }

  protected e9(): ButtonProps['disabled'] {
    return this.api.value.getNextTriggerProps().disabled === true
  }

  protected h4(): void {
    this.api.value.goToNext()
  }

  protected e10() {
    return mergeParts(this.api.value.getTableProps(), {
      class: styles.grid,
      key: this.api.value.visibleRange.start.toString(),
      tabindex: undefined,
      'aria-label': this.named.value,
      'data-travel': this.travel.value,
    })
  }

  e11() {
    return this.api.value.weekDays
  }

  protected e12(weekday: Each<ReturnType<Calendar['e11']>>) {
    return weekday.long
  }

  protected e13(weekday: Each<ReturnType<Calendar['e11']>>) {
    return weekday.short
  }

  e14() {
    return this.weeks.value
  }

  protected e15(at: number) {
    return at
  }

  e16(week: Each<ReturnType<Calendar['e14']>>) {
    return week
  }

  protected e17(day: Each<ReturnType<Calendar['e16']>>) {
    return day.date.toString()
  }

  protected e18(day: Each<ReturnType<Calendar['e16']>>) {
    return day.outside
  }

  protected e19(day: Each<ReturnType<Calendar['e16']>>) {
    if (day.outside) return undefined as never
    return styles.cell
  }

  protected e20(day: Each<ReturnType<Calendar['e16']>>) {
    if (day.outside) return undefined as never
    return !day.selectable ? 'true' : undefined
  }

  protected e21(day: Each<ReturnType<Calendar['e16']>>) {
    if (day.outside) return undefined as never
    return day.selected ? 'true' : undefined
  }

  protected h5(day: Each<ReturnType<Calendar['e16']>>): void {
    if (day.outside) return
    this.api.value.setFocusedValue(day.date)
  }

  protected h6($event: KeyboardEvent, day: Each<ReturnType<Calendar['e16']>>): void {
    if (day.outside) return
    if ($event.key === ' ' && day.selectable)
      void ($event.preventDefault(), this.api.value.setValue([day.date]))
  }

  protected e22(day: Each<ReturnType<Calendar['e16']>>) {
    if (day.outside) return undefined as never
    return mergeParts(this.api.value.getDayTableCellTriggerProps({ value: day.date }), {
      class: styles.day,
      'data-calendar-part': 'day',
      'aria-label': day.name,
      'aria-current': day.cell.today ? 'date' : undefined,
      tabindex: day.off ? undefined : day.cell.focused ? 0 : -1,
      'data-selected': day.selected ? '' : undefined,
      'data-today': day.cell.today ? '' : undefined,
      'data-unavailable': day.unavailable ? '' : undefined,
      'data-disabled': day.off ? '' : undefined,
      onFocus: () => this.h5(day),
      onKeydown: ($event: KeyboardEvent) => this.h6($event, day),
    })
  }

  protected e23(day: Each<ReturnType<Calendar['e16']>>) {
    if (day.outside) return undefined as never
    return day.date.day
  }

  private effect1(): void {
    this.browserLanguage.value = globalThis.navigator?.language
  }

  private effect2(): void {
    this.shownMonth.value = this.api.value.visibleRange.start.toString()
  }

  private effect3(): void {
    void (
      this.monthButton.value &&
      ((held) =>
        held === null || held === document.body || (held as HTMLButtonElement).disabled === true)(
        document.activeElement,
      ) &&
      ((this.monthButton.value = false),
      requestAnimationFrame(() =>
        this.root.value
          ?.querySelector<HTMLElement>('[data-calendar-part="day"][tabindex="0"]')
          ?.focus(),
      ))
    )
  }

  private effect4(): void {
    this.release4?.()
    const ran = agentMember({
      member: 'Calendar',
      element: () => this.root.value,
      state: () => ({
        value: this.api.value.value[0]?.toString() ?? '',
        disabled: this.$p.disabled,
      }),
      actions: {
        set: {
          argument: 'text',
          run: (value) =>
            (() => {
              const date = agentDate(value, {
                min: this.$p.minValue,
                max: this.$p.maxValue,
                unavailable: this.$p.isDateUnavailable,
              })
              this.api.value.setValue([date])
              this.api.value.setFocusedValue(date)
            })(),
        },
      },
      withholds: () => this.root.value,
    })
    this.release4 = () => {
      ran()
    }
  }
}
